__all__ = ['order', 'order_target', 'order_value', 'order_target_value', 'order_market', 'order_once', 'set_commission', 'set_fixed_slippage', 'set_slippage', 'set_volume_ratio', 'set_limit_mode', 'set_yesterday_position', 'get_trades_file', 'convert_position_from_csv']
extend_to_enum(OrderType, OrderedDict([('TRADE_MARKET', 'TRADE_MARKET')]))
class MarketTrade(AbstractOrderStyle):
    def __init__(self, market_type, limit_price=0):
        self.market_type = market_type
        self.limit_price = limit_price
    @property
    def gear(self):
        return self.market_type
    def get_price(self):
        return self.limit_price
    def load(self, state):
        self.market_type = state['market_type']
    def save(self):
        return {'market_type': self.market_type}
    def type(self):
        return OrderType.TRADE_MARKET.value
    def __repr__(self):
        return '<TradeMarketOrder market_type:{}>'.format(self.market_type)
ORDER_STYLE_MAP[OrderType.TRADE_MARKET.value] = MarketTrade
@api_call_counter
@check_arg
@ExecutionContext.enforce_phase(ExecutionPhase.BEFORE_TRADING_START, ExecutionPhase.ON_HANDLE_AUCTION, ExecutionPhase.ON_HANDLE_DATA, ExecutionPhase.ON_HANDLE_TICK, ExecutionPhase.AFTER_TRADING_END, ExecutionPhase.SCHEDULED, ExecutionPhase.ON_TRADE_RSP, ExecutionPhase.ON_ORDER_RSP, ExecutionPhase.GLOBAL)
def order_market(security, amount, market_type=None, limit_price=None):
    if (security[:2] in ('11', '12')):
        strategy_log.error('可转债标的不支持市价委托类型，请修改下单方式')
        return None
    elif (market_type is None):
        strategy_log.error('市价委托时市价委托类型market_type为必传字段，委托取消')
        return None
    else:
        asset = assure_asset(security)
    try:
        market_type = int(market_type)
    except ValueError:
        strategy_log.error('市价类型传入错误，传入类型为：%s，委托取消' % market_type)
        return None
    exchange_type = EXCHANGE_TYPES_DICT.get(asset.exchange.replace('XSHG', 'SS').replace('XSHE', 'SZ'))
    if (exchange_type == '1'):
        if (REGISTRATION_CONTROL == '0'):
            if (asset.symbol[:3] in ('688', '689')):
                if (limit_price is None):
                    strategy_log.error('市价委托上证科创板股票时保护限价limit_price为必传字段，委托取消')
                    return None
                elif (market_type not in (0, 1, 2, 4)):
                    strategy_log.error('市价委托上证科创板股票时市价类型仅支持0、1、2、4类型，委托取消')
                    return None
            else:
                if (limit_price is None):
                    limit_price = 0
                if (market_type not in (1, 4)):
                    strategy_log.error('市价委托上证非科创板股票时市价类型仅支持1、4类型，委托取消')
        elif (limit_price is None):
            strategy_log.error('市价委托上证股票时保护限价limit_price为必传字段，委托取消')
            return None
        elif (market_type not in (0, 1, 2, 4)):
            strategy_log.error('市价委托上证股票时市价类型仅支持0、1、2、4类型，委托取消')
            return None
    elif (exchange_type == '2'):
        if (limit_price is None):
            limit_price = 0
        if (market_type not in (0, 2, 3, 4, 5)):
            strategy_log.error('市价委托深证股票时市价类型仅支持0、2、3、4、5类型，委托取消')
        if (amount > 0):
            entrust_direction = EntrustDirection.BUY
        elif (amount < 0):
            entrust_direction = EntrustDirection.SELL
            amount = (-amount)
        else:
            strategy_log.error('股票委托数量为0, 委托取消')
        order_obj = iq_order(asset_or_symbol=asset, amount=amount, entrust_direction=entrust_direction, style=MarketTrade(market_type, limit_price), futures_direction=FuturesDirection.OPEN)
        return (order_obj.order_id if order_obj else None)
    else:
        strategy_log.error('不支持的市价委托市场：%s，委托取消' % exchange_type)
@check_arg
@ExecutionContext.enforce_phase(ExecutionPhase.ON_HANDLE_DATA)
@arg_checker.apply_rules(arg_checker.verify_arg('sid').is_valid_asset(), arg_checker.verify_arg('amount').is_number(), arg_checker.verify_arg('priceGear').is_in([str(x) for x in list(range(1, 11))]))
def order_once(sid, amount, priceGear='1'):
    base_order(sid, amount, priceGear=priceGear)
@api_call_counter
@check_arg
@ExecutionContext.enforce_phase(ExecutionPhase.BEFORE_TRADING_START, ExecutionPhase.ON_HANDLE_AUCTION, ExecutionPhase.ON_HANDLE_DATA, ExecutionPhase.AFTER_TRADING_END, ExecutionPhase.ON_HANDLE_TICK, ExecutionPhase.SCHEDULED, ExecutionPhase.GLOBAL, ExecutionPhase.ON_ORDER_RSP, ExecutionPhase.ON_TRADE_RSP)
@arg_checker.apply_rules(arg_checker.verify_arg('security').is_valid_asset(), arg_checker.verify_arg('amount').is_number(), arg_checker.verify_arg('limit_price').is_instance((int, float, None.__class__)))
def order(security, amount, limit_price=None):
    return base_order(security, amount, limit_price)
@api_call_counter
@check_arg
@ExecutionContext.enforce_phase(ExecutionPhase.BEFORE_TRADING_START, ExecutionPhase.ON_HANDLE_AUCTION, ExecutionPhase.ON_HANDLE_DATA, ExecutionPhase.AFTER_TRADING_END, ExecutionPhase.ON_HANDLE_TICK, ExecutionPhase.SCHEDULED, ExecutionPhase.ON_ORDER_RSP, ExecutionPhase.ON_TRADE_RSP)
@arg_checker.apply_rules(arg_checker.verify_arg('security').is_valid_asset(), arg_checker.verify_arg('amount').is_number(), arg_checker.verify_arg('limit_price').is_instance((int, float, None.__class__)))
def order_target(security, amount, limit_price=None):
    asset = assure_asset(security)
    if (asset.symbol.replace('XSHG', 'SS').replace('XSHE', 'SZ') in NATIONAL_DEBT_LIST):
        strategy_log.error('委托失败，错误原因：逆回购代码【%s】不支持用order_target接口下单' % security)
        return None
    else:
        position = engine_instance().get_positions(asset.symbol)
        if (position is None):
            strategy_log.error('股票代码%s获取持仓对象失败，委托失败' % security)
            return None
        else:
            current_amount = position.amount
            amount_tmp = (amount - current_amount)
            if (asset.symbol[:2] in ('11', '12')):
                unit = 10
            else:
                unit = 100
            if (amount != 0):
                amount = (amount_tmp // unit * unit)
            else:
                amount = amount_tmp
            return base_order(security, amount, limit_price=limit_price)
@api_call_counter
@check_arg
@ExecutionContext.enforce_phase(ExecutionPhase.BEFORE_TRADING_START, ExecutionPhase.ON_HANDLE_AUCTION, ExecutionPhase.ON_HANDLE_DATA, ExecutionPhase.AFTER_TRADING_END, ExecutionPhase.ON_HANDLE_TICK, ExecutionPhase.SCHEDULED, ExecutionPhase.ON_ORDER_RSP, ExecutionPhase.ON_TRADE_RSP, ExecutionPhase.ON_STRATEGY_SIGNAL_RSP)
@arg_checker.apply_rules(arg_checker.verify_arg('security').is_valid_asset(), arg_checker.verify_arg('value').is_number(), arg_checker.verify_arg('limit_price').is_instance((int, float, None.__class__)))
def order_value(security, value, limit_price=None):
    asset = assure_asset(security)
    if (asset.symbol.replace('XSHG', 'SS').replace('XSHE', 'SZ') in NATIONAL_DEBT_LIST):
        strategy_log.error('委托失败，错误原因：逆回购代码【%s】不支持用order_value接口下单' % security)
        return None
    elif limit_price:
        price = limit_price
    else:
        price = engine_instance().get_last_price(asset.symbol)
        if (price == 0):
            strategy_log.error('委托失败，错误原因：代码【%s】实时行情获取失败' % security)
    if (asset.symbol[:2] in ('11', '12')):
        unit = 10
    else:
        unit = 100
    amount = (abs(value) / price // unit * unit)
    if (value < 0):
        amount = (-amount)
    return base_order(security, amount, limit_price=limit_price)
@api_call_counter
@check_arg
@ExecutionContext.enforce_phase(ExecutionPhase.BEFORE_TRADING_START, ExecutionPhase.ON_HANDLE_AUCTION, ExecutionPhase.ON_HANDLE_DATA, ExecutionPhase.AFTER_TRADING_END, ExecutionPhase.ON_HANDLE_TICK, ExecutionPhase.SCHEDULED, ExecutionPhase.ON_ORDER_RSP, ExecutionPhase.ON_TRADE_RSP)
@arg_checker.apply_rules(arg_checker.verify_arg('security').is_valid_asset(), arg_checker.verify_arg('value').is_number(), arg_checker.verify_arg('limit_price').is_instance((int, float, None.__class__)))
def order_target_value(security, value, limit_price=None):
    asset = assure_asset(security)
    if (asset.symbol.replace('XSHG', 'SS').replace('XSHE', 'SZ') in NATIONAL_DEBT_LIST):
        strategy_log.error('委托失败，错误原因：逆回购代码【%s】不支持用order_target_value接口下单' % security)
        return None
    elif limit_price:
        price = limit_price
    else:
        price = engine_instance().get_last_price(asset.symbol)
        if (price == 0):
            strategy_log.error('委托失败，错误原因：代码【%s】实时行情获取失败' % security)
    if (asset.symbol[:2] in ('11', '12')):
        unit = 10
    else:
        unit = 100
    amount = (value / price // unit * unit)
    return order_target(security, amount, limit_price)
